function wcsSendRequestToApi(form){if(!form||form.dataset.wcsApiSent)return;const fields=[...form.querySelectorAll('input,select,textarea')],payload={name:fields[0]?.value?.trim()||'',phone:fields[1]?.value?.trim()||'',course:form.querySelector('select')?.value||'',description:form.querySelector('textarea[name="description"]')?.value?.trim()||''};if(!payload.name||!payload.phone)return;form.dataset.wcsApiSent='1';fetch('/api/requests',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload),keepalive:true}).then(response=>{if(!response.ok)throw new Error('request failed');return response.json()}).then(result=>{if(result.request){const local=wcsReadRequests().filter(item=>item.id!==result.request.id);wcsWriteRequests([result.request,...local])}}).catch(()=>{form.dataset.wcsApiSent=''})}document.addEventListener('submit',event=>{const form=event.target.closest('.lead-form');if(form)wcsSendRequestToApi(form)},true);

function repairWcsPublicLinks(){const order=['courses.html','about.html','documents.html','corporate.html','contacts.html','reviews.html'];document.querySelectorAll('.header .nav').forEach(nav=>{const existing=[...nav.querySelectorAll('a')],byHref=new Map(existing.map(a=>[a.getAttribute('href'),a]));order.forEach(href=>{let a=byHref.get(href);if(!a){a=document.createElement('a');a.href=href;byHref.set(href,a)}nav.append(a)});existing.forEach(a=>{if(!order.includes(a.getAttribute('href')))a.remove()});order.forEach(href=>nav.append(byHref.get(href)))});if(typeof normalizeWcsNavigation==='function')normalizeWcsNavigation()}repairWcsPublicLinks();[100,500,1100].forEach(delay=>setTimeout(repairWcsPublicLinks,delay));document.addEventListener('click',event=>{if(event.target.closest('[data-lang]'))setTimeout(repairWcsPublicLinks,160)});
